import{_ as o,C as s,o as e,c as n,a2 as l,b as i,w as a,a as d,E,a3 as g}from"./chunks/framework.BBdhqAg0.js";const C="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",f=JSON.parse('{"title":"소송 사건 관리","description":"","frontmatter":{},"headers":[],"relativePath":"document/legal-case.md","filePath":"document/legal-case.md","lastUpdated":1793113248000}'),A={name:"document/legal-case.md"};function B(c,t,h,u,m,x){const r=s("Mermaid");return e(),n("div",null,[t[1]||(t[1]=l('<h1 id="소송-사건-관리" tabindex="-1">소송 사건 관리 <a class="header-anchor" href="#소송-사건-관리" aria-label="Permalink to &quot;소송 사건 관리&quot;">​</a></h1><p>프로젝트와 관련된 개별 소송 사건의 기초 마스터 정보(사건번호, 관할 법원, 당사자, 소송물 가액, 진행 상태 등)를 등록하고, 소송의 전 생애주기 이력을 체계적으로 관리하는 화면입니다.</p><ul><li><strong>위치</strong>: <code>문서 소송 관리 &gt; 소송 사건 관리</code></li></ul><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+C+'" alt="소송 사건 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/legal-case.png</code> 경로에 등록해 주세요.</em></p></div><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>&#39;소송 문서 관리&#39;가 소송 과정에서 발생하는 개별 서류와 증거를 보관하는 곳이라면, **&#39;소송 사건 관리&#39;**는 그 모든 서류들이 귀속되는 **&#39;사건 마스터 데이터&#39;**를 총괄하는 허브입니다. 사건의 심급(1심, 2심, 3심), 관할 법원, 당사자(원고/피고), 소송가액(소가), 소송 비용 및 진행 상태를 통합 관리하여, 프로젝트의 법적 리스크와 우발 채무를 한눈에 통제할 수 있습니다.</p>',6)),(e(),i(g,null,{default:a(()=>[E(r,{id:"mermaid-24",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%EC%82%AC%EA%B1%B4%20%EB%A7%88%EC%8A%A4%ED%84%B0%20%EB%93%B1%EB%A1%9D%3Cbr%2F%3E(%EC%82%AC%EA%B1%B4%EB%B2%88%ED%98%B8%C2%B7%EB%B2%95%EC%9B%90%C2%B7%EB%8B%B9%EC%82%AC%EC%9E%90%C2%B7%EC%86%8C%EA%B0%80)%22%5D%20--%3E%20B%5B%222.%20%EC%8B%AC%EA%B8%89%20%EB%B0%8F%20%EC%83%81%ED%83%9C%20%EC%B6%94%EC%A0%81%3Cbr%2F%3E(1%C2%B72%C2%B73%EC%8B%AC%20%2F%20%EC%A7%84%ED%96%89%C2%B7%EC%A2%85%EA%B2%B0%C2%B7%EC%B7%A8%ED%95%98)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20%EC%97%B0%EA%B4%80%20%EC%82%AC%EA%B1%B4%20%EC%B2%B4%EC%9D%B8%20%EC%97%B0%EA%B2%B0%3Cbr%2F%3E(%EC%8B%A0%EC%B2%AD%EC%82%AC%EA%B1%B4%20%E2%86%94%20%EB%B3%B8%EC%95%88%20%E2%86%94%20%EC%83%81%EC%86%8C%EC%8B%AC)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20%EC%86%8C%EC%86%A1%20%EC%84%9C%EB%A5%98%20%EC%9D%BC%EC%B2%B4%20%ED%86%B5%ED%95%A9%3Cbr%2F%3E(%EC%86%8C%EC%86%A1%20%EB%AC%B8%EC%84%9C%20%EA%B4%80%EB%A6%AC%EC%99%80%20%EC%97%B0%EB%8F%99)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20%EB%B2%95%EC%A0%81%20%EB%A6%AC%EC%8A%A4%ED%81%AC%20%EB%B3%B4%EA%B3%A0%3Cbr%2F%3E(%EC%86%8C%EC%86%A1%20%ED%98%84%ED%99%A9%20%EC%97%91%EC%85%80%20%EB%8B%A4%EC%9A%B4%EB%A1%9C%EB%93%9C)%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><ul><li><strong>소송 사건 마스터 등록 및 관리</strong>: 사건번호, 사건명, 관할 법원, 원고 및 피고, 소송물 가액(소가), 변호사 착수금/성공보수 등 종합 법률 정보 기록</li><li><strong>심급 및 진행 상태 실시간 추적</strong>: <ul><li><code>심급(Level)</code>: 1심, 2심(항소심), 3심(상고심), 신청사건 구분</li><li><code>진행 상태(Status)</code>: 진행 중, 승소 종결, 패소 종결, 일부 승소, 화해/조정, 취하 등 세분화된 상태 관리</li></ul></li><li><strong>연관 사건(Related Cases) 체인 연결</strong>: 가압류/가처분 등 보전처분 신청 사건과 본안 소송, 또는 1심 사건과 2심 항소 사건을 상호 연결하여 전체 분쟁의 히스토리를 입체적으로 추적</li><li><strong>법률 전문 다차원 필터링</strong>: 관할 법원별, 사건 성격(본안/신청/집행)별, 심급별, 진행 상태별 정밀 검색</li><li><strong>소송 현황 엑셀 리포트 추출</strong>: 경영진 보고 및 외부 회계감사용 우발 채무 검토를 위해 전체 소송 진행 목록을 표준 엑셀 보고서로 즉시 다운로드</li><li><strong>소송 문서와의 완벽한 데이터 연동</strong>: 본 화면에서 사건을 등록하면 &#39;소송 문서 관리&#39;에서 해당 사건에 귀속되는 증거 및 준비서면을 즉시 업로드 가능</li></ul><h2 id="화면-구성-및-실무-가이드" tabindex="-1">화면 구성 및 실무 가이드 <a class="header-anchor" href="#화면-구성-및-실무-가이드" aria-label="Permalink to &quot;화면 구성 및 실무 가이드&quot;">​</a></h2><h3 id="_1-목록-제어-및-다차원-필터링" tabindex="-1">1. 목록 제어 및 다차원 필터링 <a class="header-anchor" href="#_1-목록-제어-및-다차원-필터링" aria-label="Permalink to &quot;1. 목록 제어 및 다차원 필터링&quot;">​</a></h3><p>프로젝트에서 진행 중이거나 종결된 소송 사건을 조건별로 검색하는 영역입니다.</p><ul><li><strong>전문 필터 컨트롤</strong>: <ul><li><code>심급 (Level)</code>: 전체, 1심, 2심, 3심, 신청/기타</li><li><code>사건 구분 (Sort)</code>: 민사본안, 가압류/가처분, 행정소송, 형사 등</li><li><code>관할 법원 (Court)</code>: 서울중앙지방법원, 수원지방법원 등 관할 법원별 필터</li><li><code>진행 여부 (In Progress)</code>: 전체, 진행 중 사건만 보기, 종결 사건만 보기</li></ul></li><li><strong>통합 검색창</strong>: 사건번호(예: 2026가합...), 사건명, 상대방 성명/법인명으로 신속한 키워드 검색 지원</li><li><strong>엑셀 다운로드</strong>: 우측 상단의 <strong>[엑셀]</strong> 버튼을 클릭하면 현재 필터 조건에 부합하는 모든 소송 사건 명세표가 엑셀로 자동 다운로드됩니다.</li></ul><h3 id="_2-소송-사건-목록-테이블" tabindex="-1">2. 소송 사건 목록 테이블 <a class="header-anchor" href="#_2-소송-사건-목록-테이블" aria-label="Permalink to &quot;2. 소송 사건 목록 테이블&quot;">​</a></h3><p>등록된 사건들의 핵심 정보를 일람표 형태로 확인합니다.</p><ul><li><strong>주요 표시 항목</strong>: 사건번호, 사건명, 관할 법원, 심급, 원고/피고, 소송물 가액(원), 진행 상태 배지</li><li><strong>원클릭 빠른 필터</strong>: 테이블 내의 법원 명칭이나 사건 구분 배지를 클릭하면 해당 조건으로 목록이 즉시 재필터링됩니다.</li></ul><h3 id="_3-사건-상세-정보-view" tabindex="-1">3. 사건 상세 정보 (View) <a class="header-anchor" href="#_3-사건-상세-정보-view" aria-label="Permalink to &quot;3. 사건 상세 정보 (View)&quot;">​</a></h3><p>특정 소송 사건의 마스터 데이터와 연관된 모든 진행 경과를 확인하는 화면입니다.</p><ul><li><strong>사건 기본 개요</strong>: 사건번호, 관할 법원, 재판부, 원고/피고 대리인(담당 로펌/변호사), 소송가액, 청구 취지 요약</li><li><strong>연관 사건 리스트</strong>: 본 사건과 연결된 상위 심급(항소심)이나 사전 신청 사건(가압류 등)의 링크가 제공되어, 클릭 한 번으로 관련 사건으로 즉시 이동 가능</li><li><strong>소송 문서 바로가기</strong>: 본 사건에 등록된 소장, 준비서면, 증거 서류 목록을 확인하고 해당 문서로 바로 이동할 수 있습니다.</li></ul><h3 id="_4-사건-등록-및-수정-form" tabindex="-1">4. 사건 등록 및 수정 (Form) <a class="header-anchor" href="#_4-사건-등록-및-수정-form" aria-label="Permalink to &quot;4. 사건 등록 및 수정 (Form)&quot;">​</a></h3><p>새로운 소송 사건을 개설하거나 판결 선고 등 변경 사항을 업데이트하는 화면입니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">입력 항목</th><th style="text-align:center;">필수 여부</th><th style="text-align:left;">상세 설명 및 실무 팁</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>사건번호</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">대한민국 법원 표준 사건번호 형식(예: <code>2026가합123456</code>)으로 정확히 입력합니다.</td></tr><tr><td style="text-align:left;"><strong>사건명</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">법원 소장에 기재된 공식 사건명(예: <em>공사대금 청구의 소</em>, <em>소유권이전등기</em>)을 입력합니다.</td></tr><tr><td style="text-align:left;"><strong>관할 법원</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">재판이 진행되는 관할 법원(예: 서울중앙지방법원)을 선택합니다.</td></tr><tr><td style="text-align:left;"><strong>심급 / 사건구분</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">1심/2심/3심 및 본안/신청 구분을 정확히 지정합니다.</td></tr><tr><td style="text-align:left;"><strong>원고 / 피고</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">소송 당사자 명칭을 입력하고, 당사가 원고인지 피고인지 명확히 구분합니다.</td></tr><tr><td style="text-align:left;"><strong>소송물 가액 (소가)</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">금전 청구 사건의 경우 청구 금액(원)을 숫자로 입력합니다. (회계 우발 부채 산정 기준)</td></tr><tr><td style="text-align:left;"><strong>연관 사건 지정</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">기존 등록된 사건 중 본 사건과 직접 연결되는 1심 사건이나 신청 사건을 검색하여 연결합니다.</td></tr><tr><td style="text-align:left;"><strong>진행 상태</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">사건 진행 단계(진행 중, 승소, 패소, 화해권고, 취하 등)를 선택합니다.</td></tr></tbody></table><h2 id="💡-실무-활용-팁" tabindex="-1">💡 실무 활용 팁 <a class="header-anchor" href="#💡-실무-활용-팁" aria-label="Permalink to &quot;💡 실무 활용 팁&quot;">​</a></h2><ul><li><strong>사건번호 입력 규칙 준수</strong>: 사건번호(예: <code>2026가합10293</code>)는 연도(2026) + 사건부호(가합, 가단, 카단 등) + 일련번호로 구성됩니다. 대법원 나의사건검색 포털 및 외부 시스템과의 교차 검증 기준이 되므로 띄어쓰기 없이 정확히 입력해야 합니다.</li><li><strong>연관 사건(체인) 연결의 중요성</strong>: 가압류를 먼저 걸고 본안 소송을 제기한 경우, 본안 사건 등록 시 [연관 사건] 항목에 기존 &#39;가압류 사건&#39;을 연결하세요. 1심 판결 후 항소하여 2심으로 넘어갈 때도 1심 사건을 연관 사건으로 지정해 두면, 분쟁의 발단부터 최종 대법원 판결까지의 모든 역사를 한 페이지에서 추적할 수 있습니다.</li><li><strong>회계감사 및 우발 부채 보고 활용</strong>: 연말 결산 시 공인회계사는 진행 중인 소송의 &#39;청구 금액(소가)&#39;과 &#39;승패소 가능성&#39;을 점검합니다. [엑셀] 버튼을 통해 다운로드한 소송 현황표는 감사인 제출용 기초 자료로 직접 활용할 수 있으므로 소가와 진행 상태를 항상 최신으로 유지하세요.</li></ul>',17))])}const p=o(A,[["render",B]]);export{f as __pageData,p as default};
